#!/usr/bin/env bash
# Run clang-tidy static analysis over odin, argcv, and ipsw C/C++ sources using
# ./tool/clang/bin/clang-tidy. Compile flags come from
# $BUILD_DIR/compile_commands.json, regenerated by gn at the start of
# every run. Checks are configured in the repository-root .clang-tidy, with
# a relaxed override in odin/testing/.clang-tidy for test code.
#
# Usage:
#   ./tidy.sh                                  # all odin, argcv, and ipsw TUs, uses out/
#   ./tidy.sh odin/protocol.c argcv/argcv.c      # only selected TU(s)
#   ./tidy.sh ipsw/main.c                      # analyze ipsw (macOS builds only)
#   ./tidy.sh --staged                         # only staged odin/argcv/ipsw TU changes
#   JOBS=4 ./tidy.sh                           # limit parallelism
#   BUILD_DIR=out/linux ./tidy.sh              # CI / cross builds
#
# Staged mode heuristic: staged .c/.cc/.cpp files are tidied directly;
# staged .h/.hpp files also pull in sibling .c/.cc/.cpp files (same basename)
# when present. Header-only changes with no sibling TU are skipped --
# run without --staged to be exhaustive.
# ipsw is included only when its target is enabled in the selected build.

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "$0")" && pwd)"
GN="$REPO_ROOT/tool/gn"
CLANG_TIDY="$REPO_ROOT/tool/clang/bin/clang-tidy"
SOURCE_DIRS=("$REPO_ROOT/odin" "$REPO_ROOT/argcv" "$REPO_ROOT/ipsw")
BUILD_DIR="${BUILD_DIR:-$REPO_ROOT/out}"
HEADER_FILTER="(^|/)(odin|argcv|ipsw)/.*"

default_jobs() {
    if command -v nproc >/dev/null 2>&1; then
        nproc
    elif command -v getconf >/dev/null 2>&1; then
        getconf _NPROCESSORS_ONLN 2>/dev/null || echo 1
    elif command -v sysctl >/dev/null 2>&1; then
        sysctl -n hw.ncpu 2>/dev/null || echo 1
    else
        echo 1
    fi
}

JOBS="${JOBS:-$(default_jobs)}"
case "$JOBS" in
    ''|*[!0-9]*|0)
        echo "error: JOBS must be a positive integer, got '$JOBS'" >&2
        exit 1
        ;;
esac

STAGED_MODE=0
POSITIONAL=()
while [ "$#" -gt 0 ]; do
    case "$1" in
        --staged)
            STAGED_MODE=1
            shift
            ;;
        --diff)
            echo "error: --diff has been replaced by --staged" >&2
            exit 1
            ;;
        --)
            shift
            while [ "$#" -gt 0 ]; do
                POSITIONAL+=("$1")
                shift
            done
            ;;
        -*)
            echo "error: unknown flag '$1'" >&2
            exit 1
            ;;
        *)
            POSITIONAL+=("$1")
            shift
            ;;
    esac
done

if [ "$STAGED_MODE" -eq 1 ] && [ "${#POSITIONAL[@]}" -gt 0 ]; then
    echo "error: --staged cannot be combined with explicit files" >&2
    exit 1
fi

if [ ! -x "$GN" ]; then
    echo "error: $GN not found or not executable" >&2
    echo "       run ./sync_tools.sh first" >&2
    exit 1
fi

if [ ! -x "$CLANG_TIDY" ]; then
    echo "error: $CLANG_TIDY not found or not executable" >&2
    echo "       run ./sync_tools.sh first" >&2
    exit 1
fi

for dir in "${SOURCE_DIRS[@]}"; do
    if [ ! -d "$dir" ]; then
        echo "error: $dir not found" >&2
        exit 1
    fi
done

is_tu() {
    case "$1" in
        *.c|*.cc|*.cpp) return 0 ;;
        *) return 1 ;;
    esac
}

is_header() {
    case "$1" in
        *.h|*.hpp) return 0 ;;
        *) return 1 ;;
    esac
}

# Regenerate compile_commands.json so it tracks current GN args / sources.
# gn gen is incremental and idempotent; safe to run on every invocation.
echo "regenerating $BUILD_DIR/compile_commands.json"
"$GN" gen "$BUILD_DIR" \
    --add-export-compile-commands="//odin/*" \
    --add-export-compile-commands="//argcv/*" \
    --add-export-compile-commands="//ipsw/*" >/dev/null

# The ipsw target depends on macOS headers and is absent from non-macOS builds.
IPSW_TARGET="$("$GN" ls "$BUILD_DIR" //ipsw:ipsw)"
if [ -z "$IPSW_TARGET" ]; then
    SOURCE_DIRS=("$REPO_ROOT/odin" "$REPO_ROOT/argcv")
    echo "skipping ipsw/: target is not enabled in $BUILD_DIR"
fi

FILES=()
if [ "$STAGED_MODE" -eq 1 ]; then
    echo "collecting staged odin, argcv, and ipsw changes"
    RAW=()
    while IFS= read -r -d '' rel; do
        case "$rel" in
            odin/*|argcv/*) ;;
            ipsw/*) [ -n "$IPSW_TARGET" ] || continue ;;
            *) continue ;;
        esac
        abs="$REPO_ROOT/$rel"
        [ -f "$abs" ] || continue
        if is_tu "$abs"; then
            RAW+=("$abs")
        elif is_header "$abs"; then
            base="${abs%.*}"
            for ext in c cc cpp; do
                sibling="$base.$ext"
                if [ -f "$sibling" ]; then
                    RAW+=("$sibling")
                fi
            done
        fi
    done < <(git -C "$REPO_ROOT" diff --cached --name-only -z --diff-filter=ACMRTUB -- odin argcv ipsw)
    if [ "${#RAW[@]}" -gt 0 ]; then
        while IFS= read -r f; do
            FILES+=("$f")
        done < <(printf '%s\n' "${RAW[@]}" | sort -u)
    fi
elif [ "${#POSITIONAL[@]}" -gt 0 ]; then
    for arg in "${POSITIONAL[@]}"; do
        if [[ "$arg" = /* ]]; then
            f="$arg"
        else
            f="$REPO_ROOT/${arg#./}"
        fi

        if [ ! -f "$f" ]; then
            echo "error: $arg not found" >&2
            exit 1
        fi

        case "$f" in
            "$REPO_ROOT"/odin/*|"$REPO_ROOT"/argcv/*) ;;
            "$REPO_ROOT"/ipsw/*)
                if [ -z "$IPSW_TARGET" ]; then
                    echo "error: $arg requires a macOS build with the ipsw target enabled" >&2
                    exit 1
                fi
                ;;
            *)
                echo "error: $arg is not under odin/, argcv/, or ipsw/" >&2
                exit 1
                ;;
        esac

        if ! is_tu "$f"; then
            echo "error: $arg is not a C/C++ translation unit" >&2
            exit 1
        fi

        FILES+=("$f")
    done
else
    while IFS= read -r f; do
        FILES+=("$f")
    done < <(find "${SOURCE_DIRS[@]}" \
        -type f \
        \( -name '*.c' -o -name '*.cc' -o -name '*.cpp' \) \
        -print | sort)
fi

STATUS=0
COUNT="${#FILES[@]}"

if [ "$COUNT" -eq 0 ]; then
    if [ "$STAGED_MODE" -eq 1 ]; then
        echo "no staged odin, argcv, or ipsw C/C++ translation units found"
    else
        echo "no C/C++ translation units found under odin/, argcv/, or ipsw/"
    fi
    exit 0
fi

LOG_DIR="$(mktemp -d "${TMPDIR:-/tmp}/tidy-monorepo.XXXXXX")"
cleanup() {
    rm -rf "$LOG_DIR"
}
trap cleanup EXIT

log_path_for() {
    local rel="${1#$REPO_ROOT/}"
    rel="${rel//\//__}"
    printf '%s/%s.log' "$LOG_DIR" "$rel"
}

run_tidy_one() {
    local f="$1"
    local rel="${f#$REPO_ROOT/}"
    local log
    log="$(log_path_for "$f")"

    {
        echo "tidying $rel"
        "$CLANG_TIDY" \
            -p "$BUILD_DIR" \
            --quiet \
            --header-filter="$HEADER_FILTER" \
            "$f"
    } >"$log" 2>&1
}

export REPO_ROOT BUILD_DIR CLANG_TIDY HEADER_FILTER LOG_DIR
export -f log_path_for run_tidy_one

echo "tidying $COUNT translation unit(s) with $JOBS parallel job(s)"
if ! printf '%s\0' "${FILES[@]}" | xargs -0 -n 1 -P "$JOBS" bash -c 'run_tidy_one "$1"' _; then
    STATUS=1
fi

for f in "${FILES[@]}"; do
    cat "$(log_path_for "$f")"
done

if [ "$STATUS" -eq 0 ]; then
    echo "done. tidied $COUNT translation unit(s), no issues."
else
    echo "done. tidied $COUNT translation unit(s), issues found." >&2
fi
exit $STATUS
